import{_ as a,o as r,c as t,a3 as s}from"./chunks/framework.B5WAEDB7.js";const o="/assets/images/IOyLj4i.jpg",p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/domain-name-system.md","filePath":"core-concepts/domain-name-system.md"}'),i={name:"core-concepts/domain-name-system.md"};function n(l,e,c,d,m,h){return r(),t("div",null,[...e[0]||(e[0]=[s('<h2 id="domain-name-system" tabindex="-1">Domain name system <a class="header-anchor" href="#domain-name-system" aria-label="Permalink to &quot;Domain name system&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Domain name system.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p align="center"><img src="'+o+'"><br><i><a href="http://www.slideshare.net/srikrupa5/dns-security-presentation-issa">Source: DNS security presentation</a></i></p><p>A Domain Name System (DNS) translates a domain name such as www.example.com to an IP address.</p><p>DNS is hierarchical, with a few authoritative servers at the top level. Your router or ISP provides information about which DNS server(s) to contact when doing a lookup. Lower level DNS servers cache mappings, which could become stale due to DNS propagation delays. DNS results can also be cached by your browser or OS for a certain period of time, determined by the <a href="https://en.wikipedia.org/wiki/Time_to_live" target="_blank" rel="noreferrer">time to live (TTL)</a>.</p><ul><li><strong>NS record (name server)</strong> - Specifies the DNS servers for your domain/subdomain.</li><li><strong>MX record (mail exchange)</strong> - Specifies the mail servers for accepting messages.</li><li><strong>A record (address)</strong> - Points a name to an IP address.</li><li><strong>CNAME (canonical)</strong> - Points a name to another name or <code>CNAME</code> (example.com to www.example.com) or to an <code>A</code> record.</li></ul><p>Services such as <a href="https://www.cloudflare.com/dns/" target="_blank" rel="noreferrer">CloudFlare</a> and <a href="https://aws.amazon.com/route53/" target="_blank" rel="noreferrer">Route 53</a> provide managed DNS services. Some DNS services can route traffic through various methods:</p><ul><li><a href="https://www.jscape.com/blog/load-balancing-algorithms" target="_blank" rel="noreferrer">Weighted round robin</a><ul><li>Prevent traffic from going to servers under maintenance</li><li>Balance between varying cluster sizes</li><li>A/B testing</li></ul></li><li><a href="https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/routing-policy-latency.html" target="_blank" rel="noreferrer">Latency-based</a></li><li><a href="https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/routing-policy-geo.html" target="_blank" rel="noreferrer">Geolocation-based</a></li></ul><h3 id="disadvantage-s-dns" tabindex="-1">Disadvantage(s): DNS <a class="header-anchor" href="#disadvantage-s-dns" aria-label="Permalink to &quot;Disadvantage(s): DNS&quot;">​</a></h3><ul><li>Accessing a DNS server introduces a slight delay, although mitigated by caching described above.</li><li>DNS server management could be complex and is generally managed by <a href="http://superuser.com/questions/472695/who-controls-the-dns-servers/472729" target="_blank" rel="noreferrer">governments, ISPs, and large companies</a>.</li><li>DNS services have recently come under <a href="http://dyn.com/blog/dyn-analysis-summary-of-friday-october-21-attack/" target="_blank" rel="noreferrer">DDoS attack</a>, preventing users from accessing websites such as Twitter without knowing Twitter&#39;s IP address(es).</li></ul><h3 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h3><ul><li><a href="https://technet.microsoft.com/en-us/library/dd197427(v=ws.10).aspx" target="_blank" rel="noreferrer">DNS architecture</a></li><li><a href="https://en.wikipedia.org/wiki/Domain_Name_System" target="_blank" rel="noreferrer">Wikipedia</a></li><li><a href="https://support.dnsimple.com/categories/dns/" target="_blank" rel="noreferrer">DNS articles</a></li></ul>',12)])])}const g=a(i,[["render",n]]);export{p as __pageData,g as default};
